INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(57,'call-1790680350651','user','Tell me about yourself.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(58,'call-1790680350651','assistant','I’m Vaami, your voice‑activated assistant.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(59,'call-1790680350651','assistant','I’m here to answer questions, help you stay organized, and make everyday tasks a little easier—all in a friendly, conversational way.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(60,'call-1790680350651','assistant','What can I do for you today?','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(61,'call-1790680350651','user','Can you plan my date?','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(62,'call-1790680350651','assistant','I’d love to help!','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(63,'call-1790680350651','assistant','What’s your vibe—relaxed dinner, fun activity, or something outdoors?','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(64,'call-1790680350651','assistant','And do you have a budget or a neighborhood in mind?','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(65,'call-1790680350651','user','Something out of it.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(66,'call-1790680350651','assistant','Got it—something a little off‑beat.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(67,'call-1790680350651','assistant','Any preferences: adventure, arts, food, or a mix?','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(68,'call-1790680350651','assistant','And what’s your budget range?','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(69,'call-1790680350651','user','Mix.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(70,'call-1790680350651','assistant','Sure!','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(71,'call-1790680350651','assistant',replace('Here’s a fun, off‑beat mix‑and‑match date that’s easy to adapt to any budget:\n\n**','\n',char(10)),'2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(72,'call-1790680350651','assistant','1.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(73,'call-1790680350651','assistant',replace('Start with a “secret” art pop‑up (30 min)**\n- Look up a local pop‑up gallery, street‑art exhibit, or a temporary installation (often free or $5‑$10).','\n',char(10)),'2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(74,'call-1790680350651','assistant','It’s a cool conversation starter and gives you something unexpected to explore together.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(75,'call-1790680350651','assistant','**2.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(76,'call-1790680350651','assistant',replace('DIY “tasting trail” (45 min)**\n- Pick three nearby spots—maybe a coffee cart, a tiny bakery, and a craft‑beer or mocktail stand.','\n',char(10)),'2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(77,'call-1790680350651','assistant','Grab a small sample at each place (think a latte, a pastry bite, a mini brew).','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(78,'call-1790680350651','assistant','You’ll get a quick taste tour without a huge bill.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(79,'call-1790680350651','assistant','**3.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(80,'call-1790680350651','assistant',replace('Interactive activity (1 hr)**\n- Try an escape‑room‑style puzzle bar, a VR arcade, or a board‑game café.','\n',char(10)),'2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(81,'call-1790680350651','assistant','If you want to keep it low‑key, bring a portable puzzle (like a mini‑jigsaw) to a park and solve it together.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(82,'call-1790680350651','assistant','**4.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(83,'call-1790680350651','assistant',replace('Sunset “chill” spot (30 min)**\n- Head to a scenic overlook, rooftop garden, or lakeside bench.','\n',char(10)),'2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(84,'call-1790680350651','assistant','Bring a lightweight blanket and a portable speaker for low‑key background music.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(85,'call-1790680350651','assistant','It’s a relaxed way to wind down and chat.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(86,'call-1790680350651','assistant','**5.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(87,'call-1790680350651','assistant',replace('Sweet finale (15 min)**\n- Grab a single‑serve ice‑cream or a fancy dessert from a nearby shop and enjoy it while the city lights come on.','\n',char(10)),'2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(88,'call-1790680350651','assistant',replace('**Quick tips**\n- **Timing:** Aim for a 3‑4 hour window (late afternoon to early evening).','\n',char(10)),'2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(89,'call-1790680350651','assistant','- **Budget:** You can keep it under $30 per person if you pick free art events and budget‑friendly food spots.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(90,'call-1790680350651','assistant','- **Prep:** Check social‑media event pages or apps like “Eventbrite” for pop‑ups, and make a quick reservation for the interactive venue if needed.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(91,'call-1790680350651','assistant','Enjoy the mix of surprise, flavors, and a dash of adventure!','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(92,'call-1790680350651','assistant','Let me know if you’d like specific venues in your city.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(93,'call-1790680350651','user','Thank you.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(94,'call-1790680350651','assistant','You’re welcome!','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(95,'call-1790680350651','assistant','Anything else I can help with?','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(96,'call-1790680350651','user','You.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(97,'call-1790680350651','assistant','I’m Vaami—a friendly, voice‑first assistant that helps with quick answers, reminders, planning, and little everyday tasks.','2026-09-29 11:12:30');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(98,'call-1790680350651','assistant','Just let me know what you need, and I’ll keep it short and natural.','2026-09-29 11:12:30');
