INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(172,'call-1790683478893','user','interesting.','2026-09-29 12:04:39');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(173,'call-1790683478893','assistant','Sure!','2026-09-29 12:04:39');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(174,'call-1790683478893','assistant','Did you know octopuses have three hearts?','2026-09-29 12:04:39');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(175,'call-1790683478893','assistant','Two pump blood to their gills, and the third sends it to the rest of their body.','2026-09-29 12:04:39');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(176,'call-1790683478893','assistant','And their blood is blue because it uses copper instead of iron to carry oxygen—perfect for the cold, low‑oxygen depths they love to explore.','2026-09-29 12:04:39');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(177,'call-1790683478893','assistant','Pretty wild, right?','2026-09-29 12:04:39');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(178,'call-1790683478893','user','Wow. Wow. It has three hours.','2026-09-29 12:04:39');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(179,'call-1790683478893','user','Nice.','2026-09-29 12:04:39');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(180,'call-1790683478893','assistant','Glad you liked it!','2026-09-29 12:04:39');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(181,'call-1790683478893','assistant','Want to hear another fun fact?','2026-09-29 12:04:39');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(182,'call-1790683478893','user','Yeah. Of course.','2026-09-29 12:04:39');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(183,'call-1790683478893','assistant','Here’s a cool one: Honey never spoils.','2026-09-29 12:04:39');
INSERT INTO "transcripts" ("id","call_id","speaker","text","timestamp") VALUES(184,'call-1790683478893','assistant','Archaeologists have found pots of edible honey in ancient Egyptian tombs that are still good after thousands of years!','2026-09-29 12:04:39');
